-- Phase 5D: Knowledge Library & Tools.
-- Forward-only additive migration. Library content, document versions, client
-- shares, calculator plugins, and personal configurations are provider-owned
-- and are never exposed through direct authenticated table access.
begin;

insert into public.permissions(code,name,description) values
 ('library.view','View knowledge library','View authorized library content and published tools.'),
 ('library.create','Create library content','Create protocols, research, and reference records.'),
 ('library.edit','Edit library content','Edit draft library content and metadata.'),
 ('library.approve','Approve library content','Approve content submitted for publication.'),
 ('library.publish','Publish library content','Publish or archive approved content.'),
 ('library.download','Download library content','Download authorized library documents.'),
 ('library.print','Print library content','Print authorized library documents.'),
 ('library.share_client','Share client-safe library content','Share published client-safe content with clients.'),
 ('library.categories.manage','Manage library navigation','Manage extensible sections, categories, and tags.'),
 ('calculator.manage','Manage calculator plugins','Register, version, approve, publish, and link calculator plugins.'),
 ('calculator.use','Use published calculators','View approved published calculator plugin metadata.'),
 ('calculator.personal','Manage personal calculator configurations','Create and edit only the signed-in salesperson configuration templates.')
on conflict(code) do nothing;

insert into public.role_permissions(role_id,permission_id)
select r.id,p.id from public.roles r cross join public.permissions p
where (r.code in('SUPER_ADMIN','ADMIN') and p.code in(
  'library.view','library.create','library.edit','library.approve','library.publish','library.download','library.print','library.share_client','library.categories.manage','calculator.manage','calculator.use','calculator.personal'))
   or (r.code in('STAFF','WAREHOUSE') and p.code in('library.view','library.download','library.print','calculator.use'))
   or (r.code='STAFF' and p.code='calculator.personal')
   or (r.code in('CLIENT_ADMIN','CLIENT_USER') and p.code in('library.view','library.download','library.print'))
on conflict do nothing;

-- Global section definitions are intentionally reusable by every provider.
-- Provider-specific custom sections may be added without changing this model.
create table public.knowledge_library_sections(
 id uuid primary key default extensions.gen_random_uuid(),
 organization_id uuid references public.organizations(id) on delete restrict,
 code text not null check(code~'^[a-z][a-z0-9_-]{1,79}$'),
 name text not null check(length(trim(name)) between 1 and 160),
 description text not null default '',
 section_type text not null check(section_type in('protocols','research','calculators','custom')),
 status text not null default 'active' check(status in('active','inactive')),
 display_order integer not null default 100 check(display_order>=0),
 created_by_user_id uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique nulls not distinct(organization_id,code)
);
insert into public.knowledge_library_sections(organization_id,code,name,description,section_type,display_order)
values
 (null,'protocols','Protocols','Approved operational and client-safe protocols.','protocols',10),
 (null,'research','Research & Reference','Research papers, citations, and educational reference materials.','research',20),
 (null,'calculators','Calculators & Tools','Published calculator plugin metadata and approved relationships.','calculators',30)
on conflict do nothing;

create table public.knowledge_library_categories(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,
 section_id uuid not null references public.knowledge_library_sections(id) on delete restrict,parent_category_id uuid references public.knowledge_library_categories(id) on delete restrict,
 name text not null check(length(trim(name)) between 1 and 160),slug text not null check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),description text not null default '',status text not null default 'active' check(status in('active','inactive')),display_order integer not null default 100 check(display_order>=0),
 created_by_user_id uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,section_id,slug)
);

create table public.knowledge_library_tags(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,
 name text not null check(length(trim(name)) between 1 and 80),slug text not null check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),created_by_user_id uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,slug)
);

create table public.knowledge_library_items(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,
 section_id uuid not null references public.knowledge_library_sections(id) on delete restrict,category_id uuid references public.knowledge_library_categories(id) on delete restrict,
 item_type text not null check(item_type in('protocol','research','resource')),slug text not null check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),status text not null default 'active' check(status in('active','archived')),
 current_version_id uuid,created_by_user_id uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,slug)
);

create table public.knowledge_library_item_versions(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,
 item_id uuid not null references public.knowledge_library_items(id) on delete restrict,version_number integer not null check(version_number>0),
 title text not null check(length(trim(title)) between 1 and 240),summary text not null default '',body text not null default '',
 document_metadata jsonb not null default '{}' check(jsonb_typeof(document_metadata)='object'),source_metadata jsonb not null default '{}' check(jsonb_typeof(source_metadata)='object'),
 visibility text not null default 'internal' check(visibility in('internal','fulfillment','salesperson','client_safe')),client_safe boolean not null default false,
 status text not null default 'draft' check(status in('draft','review','approved','published','archived')),
 content_hash text not null default '',created_by_user_id uuid references auth.users(id),reviewed_by_user_id uuid references auth.users(id),approved_by_user_id uuid references auth.users(id),published_by_user_id uuid references auth.users(id),
 reviewed_at timestamptz,approved_at timestamptz,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(organization_id,id),unique(organization_id,item_id,version_number)
);
alter table public.knowledge_library_items add constraint knowledge_library_items_current_version_fk foreign key(organization_id,current_version_id) references public.knowledge_library_item_versions(organization_id,id) on delete restrict;
create table public.knowledge_library_item_tags(
 item_id uuid not null references public.knowledge_library_items(id) on delete restrict,tag_id uuid not null references public.knowledge_library_tags(id) on delete restrict,created_at timestamptz not null default now(),primary key(item_id,tag_id)
);
create table public.knowledge_library_version_events(
 id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete restrict,version_id uuid not null references public.knowledge_library_item_versions(id) on delete restrict,
 old_status text,new_status text not null,action text not null,metadata jsonb not null default '{}',actor_user_id uuid references auth.users(id),created_at timestamptz not null default now()
);
create table public.knowledge_library_share_grants(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,client_organization_id uuid not null references public.organizations(id) on delete restrict,item_id uuid not null references public.knowledge_library_items(id) on delete restrict,version_id uuid not null references public.knowledge_library_item_versions(id) on delete restrict,
 status text not null default 'active' check(status in('active','inactive')),effective_from timestamptz not null default now(),effective_to timestamptz,created_by_user_id uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(effective_to is null or effective_to>effective_from),unique(organization_id,id),unique(organization_id,client_organization_id,item_id,version_id)
);
create table public.knowledge_library_delivery_events(
 id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete restrict,item_id uuid not null references public.knowledge_library_items(id) on delete restrict,version_id uuid not null references public.knowledge_library_item_versions(id) on delete restrict,client_organization_id uuid references public.organizations(id) on delete restrict,delivery_mode text not null check(delivery_mode in('print','download')),actor_user_id uuid references auth.users(id),created_at timestamptz not null default now()
);

-- Calculator framework: registration and execution are deliberately separate.
-- This phase stores manifests, schemas, unit declarations, approved source links,
-- and personal templates; it does not execute a calculator or prescribe dosing.
create table public.calculator_plugins(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,
 slug text not null check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),name text not null check(length(trim(name)) between 1 and 160),description text not null default '',plugin_kind text not null check(plugin_kind in('external','native')),status text not null default 'active' check(status in('active','inactive')),
 created_by_user_id uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,slug),unique(organization_id,id)
);
create table public.calculator_plugin_versions(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,plugin_id uuid not null references public.calculator_plugins(id) on delete restrict,
 version text not null check(version~'^[0-9A-Za-z][0-9A-Za-z._-]{0,63}$'),manifest jsonb not null default '{}' check(jsonb_typeof(manifest)='object'),input_schema jsonb not null default '{}' check(jsonb_typeof(input_schema)='object'),output_schema jsonb not null default '{}' check(jsonb_typeof(output_schema)='object'),unit_schema jsonb not null default '{}' check(jsonb_typeof(unit_schema)='object'),engine_reference text not null default '',dosing_mode text not null default 'none' check(dosing_mode in('none','reference_only')),
 status text not null default 'draft' check(status in('draft','review','approved','published','archived')),checksum text not null default '',created_by_user_id uuid references auth.users(id),approved_by_user_id uuid references auth.users(id),published_by_user_id uuid references auth.users(id),approved_at timestamptz,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,plugin_id,version),unique(organization_id,id)
);
create table public.calculator_plugin_source_links(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,plugin_version_id uuid not null references public.calculator_plugin_versions(id) on delete restrict,library_item_id uuid not null references public.knowledge_library_items(id) on delete restrict,library_version_id uuid not null references public.knowledge_library_item_versions(id) on delete restrict,relationship_type text not null check(relationship_type in('approved_protocol','approved_data_source')),created_by_user_id uuid references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,plugin_version_id,library_version_id,relationship_type)
);
create table public.calculator_personal_configurations(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,owner_user_id uuid not null references auth.users(id) on delete restrict,plugin_version_id uuid not null references public.calculator_plugin_versions(id) on delete restrict,
 name text not null check(length(trim(name)) between 1 and 160),configuration jsonb not null default '{}' check(jsonb_typeof(configuration)='object'),status text not null default 'active' check(status in('active','inactive')),version integer not null default 1 check(version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,owner_user_id,plugin_version_id,name)
);
create table public.calculator_configuration_events(
 id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete restrict,configuration_id uuid not null references public.calculator_personal_configurations(id) on delete restrict,action text not null,metadata jsonb not null default '{}',actor_user_id uuid references auth.users(id),created_at timestamptz not null default now()
);

do $$declare t text;begin foreach t in array array['knowledge_library_sections','knowledge_library_categories','knowledge_library_tags','knowledge_library_items','knowledge_library_item_versions','knowledge_library_item_tags','knowledge_library_version_events','knowledge_library_share_grants','knowledge_library_delivery_events','calculator_plugins','calculator_plugin_versions','calculator_plugin_source_links','calculator_personal_configurations','calculator_configuration_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
revoke all on sequence public.knowledge_library_version_events_id_seq,public.knowledge_library_delivery_events_id_seq,public.calculator_configuration_events_id_seq from public,anon,authenticated;
grant usage,select on sequence public.knowledge_library_version_events_id_seq,public.knowledge_library_delivery_events_id_seq,public.calculator_configuration_events_id_seq to service_role;

create or replace function private.phase5d_provider(provider_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organizations where id=provider_id and status='active' and organization_type in('fulfillment_company','white_label'));$$;
revoke all on function private.phase5d_provider(uuid) from public,anon,authenticated;grant execute on function private.phase5d_provider(uuid) to authenticated;
create or replace function private.phase5d_provider_role(provider_id uuid,allowed_visibility text default null) returns boolean language sql stable security definer set search_path='' as $$select private.is_super_admin() or private.has_permission(provider_id,'library.approve') or (allowed_visibility is null and private.has_permission(provider_id,'library.view')) or (allowed_visibility in('fulfillment','salesperson','client_safe') and private.has_permission(provider_id,'library.view'));$$;
revoke all on function private.phase5d_provider_role(uuid,text) from public,anon,authenticated;grant execute on function private.phase5d_provider_role(uuid,text) to authenticated;

create or replace function private.validate_phase5d_library_item() returns trigger language plpgsql security definer set search_path='' as $$declare s public.knowledge_library_sections;c public.knowledge_library_categories;begin if not private.phase5d_provider(new.organization_id) then raise exception 'Active provider required' using errcode='42501';end if;select * into s from public.knowledge_library_sections where id=new.section_id and status='active' and (organization_id is null or organization_id=new.organization_id);if s.id is null then raise exception 'Invalid library section' using errcode='22023';end if;if new.category_id is not null then select * into c from public.knowledge_library_categories where id=new.category_id and organization_id=new.organization_id and section_id=new.section_id and status='active';if c.id is null then raise exception 'Invalid library category' using errcode='22023';end if;end if;return new;end $$;
revoke all on function private.validate_phase5d_library_item() from public,anon,authenticated;
create trigger knowledge_library_item_validate before insert or update on public.knowledge_library_items for each row execute function private.validate_phase5d_library_item();

create or replace function private.validate_phase5d_library_version() returns trigger language plpgsql security definer set search_path='' as $$declare i public.knowledge_library_items;begin select * into i from public.knowledge_library_items where id=new.item_id and organization_id=new.organization_id;if i.id is null then raise exception 'Invalid library item' using errcode='22023';end if;if new.client_safe and new.visibility<>'client_safe' then raise exception 'Client-safe versions require client-safe visibility' using errcode='22023';end if;return new;end $$;
revoke all on function private.validate_phase5d_library_version() from public,anon,authenticated;
create trigger knowledge_library_version_validate before insert or update on public.knowledge_library_item_versions for each row execute function private.validate_phase5d_library_version();

create or replace function private.validate_phase5d_category() returns trigger language plpgsql security definer set search_path='' as $$declare s public.knowledge_library_sections;p public.knowledge_library_categories;begin if not private.phase5d_provider(new.organization_id) then raise exception 'Active provider required' using errcode='42501';end if;select * into s from public.knowledge_library_sections where id=new.section_id and status='active' and (organization_id is null or organization_id=new.organization_id);if s.id is null then raise exception 'Invalid library section' using errcode='22023';end if;if new.parent_category_id is not null then select * into p from public.knowledge_library_categories where id=new.parent_category_id and organization_id=new.organization_id and section_id=new.section_id;if p.id is null then raise exception 'Invalid parent category' using errcode='22023';end if;end if;return new;end $$;
revoke all on function private.validate_phase5d_category() from public,anon,authenticated;
create trigger knowledge_library_category_validate before insert or update on public.knowledge_library_categories for each row execute function private.validate_phase5d_category();

create or replace function private.validate_phase5d_calculator_version() returns trigger language plpgsql security definer set search_path='' as $$declare p public.calculator_plugins;begin select * into p from public.calculator_plugins where id=new.plugin_id and organization_id=new.organization_id and status='active';if p.id is null or new.dosing_mode not in('none','reference_only') then raise exception 'Invalid calculator plugin or dosing authority' using errcode='22023';end if;return new;end $$;
revoke all on function private.validate_phase5d_calculator_version() from public,anon,authenticated;
create trigger calculator_plugin_version_validate before insert or update on public.calculator_plugin_versions for each row execute function private.validate_phase5d_calculator_version();

create or replace function private.validate_phase5d_source_link() returns trigger language plpgsql security definer set search_path='' as $$declare p public.calculator_plugin_versions;i public.knowledge_library_items;v public.knowledge_library_item_versions;s public.knowledge_library_sections;begin select * into p from public.calculator_plugin_versions where id=new.plugin_version_id and organization_id=new.organization_id;select * into i from public.knowledge_library_items where id=new.library_item_id and organization_id=new.organization_id;select * into v from public.knowledge_library_item_versions where id=new.library_version_id and organization_id=new.organization_id and item_id=new.library_item_id;select * into s from public.knowledge_library_sections where id=i.section_id;if p.id is null or i.id is null or v.id is null or v.status not in('approved','published') or (new.relationship_type='approved_protocol' and s.section_type<>'protocols') or (new.relationship_type='approved_data_source' and s.section_type not in('research','protocols')) then raise exception 'Calculator source must reference approved content' using errcode='42501';end if;return new;end $$;
revoke all on function private.validate_phase5d_source_link() from public,anon,authenticated;
create trigger calculator_source_link_validate before insert or update on public.calculator_plugin_source_links for each row execute function private.validate_phase5d_source_link();

create or replace function private.validate_phase5d_personal_config() returns trigger language plpgsql security definer set search_path='' as $$declare p public.calculator_plugin_versions;begin select * into p from public.calculator_plugin_versions where id=new.plugin_version_id and organization_id=new.organization_id and status='published';if p.id is null or not exists(select 1 from public.organization_memberships m where m.organization_id=new.organization_id and m.user_id=new.owner_user_id and m.status='active') then raise exception 'Published calculator and active owner membership required' using errcode='42501';end if;return new;end $$;
revoke all on function private.validate_phase5d_personal_config() from public,anon,authenticated;
create trigger calculator_personal_config_validate before insert or update on public.calculator_personal_configurations for each row execute function private.validate_phase5d_personal_config();

create or replace function public.admin_save_library_section(target_id uuid,target_organization_id uuid,target_code text,target_name text,target_description text,target_section_type text,target_status text,target_display_order integer,target_expected_version integer default null) returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin if not private.has_permission(target_organization_id,'library.categories.manage') then raise exception 'Library navigation permission required' using errcode='42501';end if;if target_id is null then insert into public.knowledge_library_sections(organization_id,code,name,description,section_type,status,display_order,created_by_user_id) values(target_organization_id,lower(trim(target_code)),trim(target_name),coalesce(target_description,''),target_section_type,target_status,target_display_order,auth.uid()) returning id into rid;else update public.knowledge_library_sections set name=trim(target_name),description=coalesce(target_description,''),section_type=target_section_type,status=target_status,display_order=target_display_order,updated_at=now() where id=target_id and organization_id=target_organization_id returning id into rid;if rid is null then raise exception 'Section not found' using errcode='40001';end if;end if;perform private.write_audit_event(auth.uid(),target_organization_id,case when target_id is null then 'library.section_created' else 'library.section_updated' end,'knowledge_library_section',rid::text,jsonb_build_object('code',lower(trim(target_code))));return rid;end $$;
grant execute on function public.admin_save_library_section(uuid,uuid,text,text,text,text,text,integer,integer) to authenticated;

create or replace function public.admin_save_library_category(target_id uuid,target_organization_id uuid,target_section_id uuid,target_parent_category_id uuid,target_name text,target_slug text,target_description text,target_status text,target_display_order integer,target_expected_version integer default null) returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin if not private.has_permission(target_organization_id,'library.categories.manage') then raise exception 'Library navigation permission required' using errcode='42501';end if;if target_id is null then insert into public.knowledge_library_categories(organization_id,section_id,parent_category_id,name,slug,description,status,display_order,created_by_user_id) values(target_organization_id,target_section_id,target_parent_category_id,trim(target_name),lower(trim(target_slug)),coalesce(target_description,''),target_status,target_display_order,auth.uid()) returning id into rid;else update public.knowledge_library_categories set section_id=target_section_id,parent_category_id=target_parent_category_id,name=trim(target_name),slug=lower(trim(target_slug)),description=coalesce(target_description,''),status=target_status,display_order=target_display_order,updated_at=now() where id=target_id and organization_id=target_organization_id returning id into rid;if rid is null then raise exception 'Category not found' using errcode='40001';end if;end if;perform private.write_audit_event(auth.uid(),target_organization_id,case when target_id is null then 'library.category_created' else 'library.category_updated' end,'knowledge_library_category',rid::text,jsonb_build_object('section_id',target_section_id,'slug',lower(trim(target_slug))));return rid;end $$;
grant execute on function public.admin_save_library_category(uuid,uuid,uuid,uuid,text,text,text,text,integer,integer) to authenticated;

create or replace function public.admin_save_library_tag(target_id uuid,target_organization_id uuid,target_name text,target_slug text) returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin if not private.has_permission(target_organization_id,'library.categories.manage') then raise exception 'Library navigation permission required' using errcode='42501';end if;if target_id is null then insert into public.knowledge_library_tags(organization_id,name,slug,created_by_user_id) values(target_organization_id,trim(target_name),lower(trim(target_slug)),auth.uid()) returning id into rid;else update public.knowledge_library_tags set name=trim(target_name),slug=lower(trim(target_slug)),updated_at=now() where id=target_id and organization_id=target_organization_id returning id into rid;if rid is null then raise exception 'Tag not found' using errcode='40001';end if;end if;perform private.write_audit_event(auth.uid(),target_organization_id,case when target_id is null then 'library.tag_created' else 'library.tag_updated' end,'knowledge_library_tag',rid::text,jsonb_build_object('slug',lower(trim(target_slug))));return rid;end $$;
grant execute on function public.admin_save_library_tag(uuid,uuid,text,text) to authenticated;

create or replace function public.admin_set_library_item_tags(target_organization_id uuid,target_item_id uuid,target_tag_ids uuid[]) returns integer language plpgsql security definer set search_path='' as $$declare count_added integer;begin if not private.has_permission(target_organization_id,'library.edit') then raise exception 'Library edit permission required' using errcode='42501';end if;if not exists(select 1 from public.knowledge_library_items where id=target_item_id and organization_id=target_organization_id) then raise exception 'Library item not found' using errcode='40001';end if;if exists(select 1 from unnest(coalesce(target_tag_ids,'{}'::uuid[])) ids(id) left join public.knowledge_library_tags t on t.id=ids.id and t.organization_id=target_organization_id where t.id is null) then raise exception 'Tags must belong to the provider' using errcode='42501';end if;delete from public.knowledge_library_item_tags where item_id=target_item_id;insert into public.knowledge_library_item_tags(item_id,tag_id) select target_item_id,ids.id from unnest(coalesce(target_tag_ids,'{}'::uuid[])) ids(id) on conflict do nothing;get diagnostics count_added=row_count;perform private.write_audit_event(auth.uid(),target_organization_id,'library.item_tags_updated','knowledge_library_item',target_item_id::text,jsonb_build_object('tag_count',count_added));return count_added;end $$;
grant execute on function public.admin_set_library_item_tags(uuid,uuid,uuid[]) to authenticated;

create or replace function public.get_library_navigation(target_provider_id uuid) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('sections',coalesce((select jsonb_agg(to_jsonb(s) order by s.display_order,s.name) from public.knowledge_library_sections s where s.status='active' and (s.organization_id is null or s.organization_id=target_provider_id)),'[]'),'categories',coalesce((select jsonb_agg(to_jsonb(c) order by c.display_order,c.name) from public.knowledge_library_categories c where c.organization_id=target_provider_id and c.status='active'),'[]'),'tags',coalesce((select jsonb_agg(to_jsonb(t) order by t.name) from public.knowledge_library_tags t where t.organization_id=target_provider_id),'[]')) where private.phase5d_provider(target_provider_id) and private.has_permission(target_provider_id,'library.view');$$;
grant execute on function public.get_library_navigation(uuid) to authenticated;

create or replace function public.admin_save_library_item(target_id uuid,target_organization_id uuid,target_section_id uuid,target_category_id uuid,target_item_type text,target_slug text,target_title text,target_summary text,target_body text,target_document_metadata jsonb,target_source_metadata jsonb,target_visibility text,target_client_safe boolean,target_expected_version integer default null) returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;vid uuid;next_version integer;latest public.knowledge_library_item_versions;begin if target_id is null then if not private.has_permission(target_organization_id,'library.create') then raise exception 'Library create permission required' using errcode='42501';end if;insert into public.knowledge_library_items(organization_id,section_id,category_id,item_type,slug,created_by_user_id) values(target_organization_id,target_section_id,target_category_id,target_item_type,lower(trim(target_slug)),auth.uid()) returning id into rid;insert into public.knowledge_library_item_versions(organization_id,item_id,version_number,title,summary,body,document_metadata,source_metadata,visibility,client_safe,content_hash,created_by_user_id) values(target_organization_id,rid,1,trim(target_title),coalesce(target_summary,''),coalesce(target_body,''),coalesce(target_document_metadata,'{}'),coalesce(target_source_metadata,'{}'),target_visibility,target_client_safe,encode(extensions.digest(convert_to(coalesce(target_title,'')||coalesce(target_body,''),'utf8'),'sha256'),'hex'),auth.uid()) returning id into vid;else if not private.has_permission(target_organization_id,'library.edit') then raise exception 'Library edit permission required' using errcode='42501';end if;select * into latest from public.knowledge_library_item_versions where organization_id=target_organization_id and item_id=target_id order by version_number desc limit 1 for update;if latest.id is null then raise exception 'Library item not found' using errcode='40001';end if;if latest.status='draft' then update public.knowledge_library_item_versions set title=trim(target_title),summary=coalesce(target_summary,''),body=coalesce(target_body,''),document_metadata=coalesce(target_document_metadata,'{}'),source_metadata=coalesce(target_source_metadata,'{}'),visibility=target_visibility,client_safe=target_client_safe,content_hash=encode(extensions.digest(convert_to(coalesce(target_title,'')||coalesce(target_body,''),'utf8'),'sha256'),'hex'),updated_at=now() where id=latest.id and (target_expected_version is null or version_number=target_expected_version) returning id into vid;if vid is null then raise exception 'Draft changed or unavailable' using errcode='40001';end if;else next_version=latest.version_number+1;insert into public.knowledge_library_item_versions(organization_id,item_id,version_number,title,summary,body,document_metadata,source_metadata,visibility,client_safe,content_hash,created_by_user_id) values(target_organization_id,target_id,next_version,trim(target_title),coalesce(target_summary,''),coalesce(target_body,''),coalesce(target_document_metadata,'{}'),coalesce(target_source_metadata,'{}'),target_visibility,target_client_safe,encode(extensions.digest(convert_to(coalesce(target_title,'')||coalesce(target_body,''),'utf8'),'sha256'),'hex'),auth.uid()) returning id into vid;rid=target_id;end if;end if;perform private.write_audit_event(auth.uid(),target_organization_id,case when target_id is null then 'library.item_created' else 'library.item_draft_saved' end,'knowledge_library_item',rid::text,jsonb_build_object('version_id',vid,'item_type',target_item_type));return rid;end $$;
grant execute on function public.admin_save_library_item(uuid,uuid,uuid,uuid,text,text,text,text,text,jsonb,jsonb,text,boolean,integer) to authenticated;

create or replace function public.transition_library_version(target_version_id uuid,target_status text) returns uuid language plpgsql security definer set search_path='' as $$declare v public.knowledge_library_item_versions;i public.knowledge_library_items;allowed boolean:=false;begin select * into v from public.knowledge_library_item_versions where id=target_version_id for update;select * into i from public.knowledge_library_items where id=v.item_id and organization_id=v.organization_id;if v.id is null or i.id is null then raise exception 'Library version not found' using errcode='40001';end if;if target_status='review' and v.status='draft' and private.has_permission(v.organization_id,'library.edit') then allowed=true;update public.knowledge_library_item_versions set status='review',reviewed_by_user_id=auth.uid(),reviewed_at=now(),updated_at=now() where id=v.id;elsif target_status='draft' and v.status='review' and private.has_permission(v.organization_id,'library.edit') then allowed=true;update public.knowledge_library_item_versions set status='draft',updated_at=now() where id=v.id;elsif target_status='approved' and v.status='review' and private.has_permission(v.organization_id,'library.approve') then allowed=true;update public.knowledge_library_item_versions set status='approved',approved_by_user_id=auth.uid(),approved_at=now(),updated_at=now() where id=v.id;elsif target_status='published' and v.status='approved' and private.has_permission(v.organization_id,'library.publish') then allowed=true;update public.knowledge_library_item_versions set status='published',published_by_user_id=auth.uid(),published_at=now(),updated_at=now() where id=v.id;update public.knowledge_library_items set current_version_id=v.id,status='active',updated_at=now() where id=i.id;elsif target_status='archived' and v.status='published' and private.has_permission(v.organization_id,'library.publish') then allowed=true;update public.knowledge_library_item_versions set status='archived',updated_at=now() where id=v.id;update public.knowledge_library_items set status=case when current_version_id=v.id then 'archived' else status end,updated_at=now() where id=i.id;end if;if not allowed then raise exception 'Invalid library lifecycle transition' using errcode='42501';end if;insert into public.knowledge_library_version_events(organization_id,version_id,old_status,new_status,action,metadata,actor_user_id) values(v.organization_id,v.id,v.status,target_status,'library.version_transition',jsonb_build_object('item_id',v.item_id),auth.uid());perform private.write_audit_event(auth.uid(),v.organization_id,'library.version_'||target_status,'knowledge_library_item_version',v.id::text,jsonb_build_object('item_id',v.item_id,'old_status',v.status,'new_status',target_status));return v.id;end $$;
grant execute on function public.transition_library_version(uuid,text) to authenticated;

create or replace function public.admin_share_library_item(target_provider_id uuid,target_item_id uuid,target_version_id uuid,target_client_organization_id uuid,target_effective_from timestamptz,target_effective_to timestamptz) returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;v public.knowledge_library_item_versions;begin if not private.has_permission(target_provider_id,'library.share_client') then raise exception 'Client sharing permission required' using errcode='42501';end if;select * into v from public.knowledge_library_item_versions where id=target_version_id and organization_id=target_provider_id and item_id=target_item_id and status='published' and client_safe=true;if v.id is null or not private.phase5c_provider_client(target_provider_id,target_client_organization_id) then raise exception 'Published client-safe version and valid client required' using errcode='42501';end if;insert into public.knowledge_library_share_grants(organization_id,client_organization_id,item_id,version_id,effective_from,effective_to,created_by_user_id) values(target_provider_id,target_client_organization_id,target_item_id,target_version_id,coalesce(target_effective_from,now()),target_effective_to,auth.uid()) returning id into rid;perform private.write_audit_event(auth.uid(),target_provider_id,'library.client_share_created','knowledge_library_share_grant',rid::text,jsonb_build_object('item_id',target_item_id,'version_id',target_version_id,'client_organization_id',target_client_organization_id));return rid;end $$;
grant execute on function public.admin_share_library_item(uuid,uuid,uuid,uuid,timestamptz,timestamptz) to authenticated;

create or replace function public.get_library_context(target_provider_id uuid,target_query text default null) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('sections',coalesce((select jsonb_agg(to_jsonb(s) order by s.display_order,s.name) from public.knowledge_library_sections s where s.status='active' and (s.organization_id is null or s.organization_id=target_provider_id)),'[]'),'categories',coalesce((select jsonb_agg(to_jsonb(c) order by c.display_order,c.name) from public.knowledge_library_categories c where c.organization_id=target_provider_id and c.status='active'),'[]'),'items',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'section_id',i.section_id,'category_id',i.category_id,'item_type',i.item_type,'slug',i.slug,'status',i.status,'version_id',v.id,'version_number',v.version_number,'title',v.title,'summary',v.summary,'visibility',v.visibility,'client_safe',v.client_safe) order by v.title) from public.knowledge_library_items i join public.knowledge_library_item_versions v on v.id=i.current_version_id and v.organization_id=i.organization_id where i.organization_id=target_provider_id and i.status='active' and v.status='published' and (private.is_super_admin() or private.has_permission(target_provider_id,'library.approve') or v.visibility in('fulfillment','salesperson','client_safe')) and (target_query is null or trim(target_query)='' or v.title ilike '%'||trim(target_query)||'%' or v.summary ilike '%'||trim(target_query)||'%' or exists(select 1 from public.knowledge_library_item_tags it join public.knowledge_library_tags t on t.id=it.tag_id where it.item_id=i.id and t.name ilike '%'||trim(target_query)||'%'))),'[]'),'calculators',coalesce((select jsonb_agg(jsonb_build_object('plugin_id',p.id,'slug',p.slug,'name',p.name,'plugin_kind',p.plugin_kind,'version_id',v.id,'version',v.version,'manifest',v.manifest,'input_schema',v.input_schema,'output_schema',v.output_schema,'unit_schema',v.unit_schema,'dosing_mode',v.dosing_mode) order by p.name,v.version desc) from public.calculator_plugins p join public.calculator_plugin_versions v on v.plugin_id=p.id and v.organization_id=p.organization_id and v.status='published' where p.organization_id=target_provider_id and p.status='active' and (private.is_super_admin() or private.has_permission(target_provider_id,'calculator.use'))),'[]')) where private.phase5d_provider(target_provider_id) and private.has_permission(target_provider_id,'library.view');$$;
grant execute on function public.get_library_context(uuid,text) to authenticated;

create or replace function public.get_client_library(target_provider_id uuid,target_query text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare client_id uuid;result jsonb;begin select m.organization_id into client_id from public.organization_memberships m join public.organizations c on c.id=m.organization_id where m.user_id=auth.uid() and m.status='active' and c.organization_type='client_company' and private.phase5c_provider_client(target_provider_id,c.id) and private.has_permission(c.id,'library.view') order by m.is_primary desc limit 1;if client_id is null then raise exception 'Client library access denied' using errcode='42501';end if;select coalesce(jsonb_agg(jsonb_build_object('item_id',i.id,'version_id',v.id,'item_type',i.item_type,'title',v.title,'summary',v.summary,'section_id',i.section_id,'category_id',i.category_id,'visibility',v.visibility,'client_safe',v.client_safe) order by v.title),'[]') into result from public.knowledge_library_share_grants g join public.knowledge_library_items i on i.id=g.item_id and i.organization_id=g.organization_id join public.knowledge_library_item_versions v on v.id=g.version_id and v.organization_id=g.organization_id where g.organization_id=target_provider_id and g.client_organization_id=client_id and g.status='active' and v.status='published' and v.client_safe and g.effective_from<=now() and (g.effective_to is null or now()<g.effective_to) and (target_query is null or v.title ilike '%'||trim(target_query)||'%' or v.summary ilike '%'||trim(target_query)||'%');return result;end $$;
grant execute on function public.get_client_library(uuid,text) to authenticated;

create or replace function public.get_library_item_delivery(target_provider_id uuid,target_item_id uuid,target_version_id uuid,target_mode text) returns jsonb language plpgsql security definer set search_path='' as $$declare v public.knowledge_library_item_versions;i public.knowledge_library_items;client_id uuid;client_access boolean:=false;provider_access boolean:=false;safe_source jsonb;begin if target_mode not in('print','download') then raise exception 'Invalid delivery mode' using errcode='22023';end if;select * into v from public.knowledge_library_item_versions where id=target_version_id and organization_id=target_provider_id and item_id=target_item_id;select * into i from public.knowledge_library_items where id=target_item_id and organization_id=target_provider_id;provider_access:=private.phase5d_provider(target_provider_id) and private.has_permission(target_provider_id,case when target_mode='print' then 'library.print' else 'library.download' end) and (private.is_super_admin() or private.has_permission(target_provider_id,'library.approve') or (v.status='published' and v.visibility in('fulfillment','salesperson','client_safe')));if not provider_access then select m.organization_id into client_id from public.organization_memberships m join public.organizations c on c.id=m.organization_id where m.user_id=auth.uid() and m.status='active' and c.organization_type='client_company' and private.phase5c_provider_client(target_provider_id,c.id) and private.has_permission(c.id,case when target_mode='print' then 'library.print' else 'library.download' end) limit 1;client_access:=client_id is not null and exists(select 1 from public.knowledge_library_share_grants g where g.organization_id=target_provider_id and g.client_organization_id=client_id and g.item_id=i.id and g.version_id=v.id and g.status='active' and g.effective_from<=now() and (g.effective_to is null or now()<g.effective_to)) and v.status='published' and v.client_safe;end if;if i.id is null or v.id is null or not(provider_access or client_access) then raise exception 'Library delivery access denied' using errcode='42501';end if;safe_source:=case when client_access then jsonb_build_object('citation',v.source_metadata->'citation','title',v.source_metadata->'title','authors',v.source_metadata->'authors','url',v.source_metadata->'url','doi',v.source_metadata->'doi') else v.source_metadata end;insert into public.knowledge_library_delivery_events(organization_id,item_id,version_id,client_organization_id,delivery_mode,actor_user_id) values(target_provider_id,i.id,v.id,client_id,target_mode,auth.uid());perform private.write_audit_event(auth.uid(),target_provider_id,'library.'||target_mode,'knowledge_library_item_version',v.id::text,jsonb_build_object('item_id',i.id,'version_id',v.id,'client_organization_id',client_id));return jsonb_build_object('item_id',i.id,'version_id',v.id,'title',v.title,'summary',v.summary,'body',v.body,'item_type',i.item_type,'document_metadata',case when client_access then jsonb_build_object('file_name',v.document_metadata->'file_name','mime_type',v.document_metadata->'mime_type','size',v.document_metadata->'size') else v.document_metadata end,'source_metadata',safe_source,'delivery_mode',target_mode);end $$;
grant execute on function public.get_library_item_delivery(uuid,uuid,uuid,text) to authenticated;

create or replace function public.admin_save_calculator_plugin(target_id uuid,target_provider_id uuid,target_slug text,target_name text,target_description text,target_plugin_kind text,target_status text) returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin if not private.has_permission(target_provider_id,'calculator.manage') then raise exception 'Calculator administration permission required' using errcode='42501';end if;if target_id is null then insert into public.calculator_plugins(organization_id,slug,name,description,plugin_kind,status,created_by_user_id) values(target_provider_id,lower(trim(target_slug)),trim(target_name),coalesce(target_description,''),target_plugin_kind,target_status,auth.uid()) returning id into rid;else update public.calculator_plugins set name=trim(target_name),description=coalesce(target_description,''),plugin_kind=target_plugin_kind,status=target_status,updated_at=now() where id=target_id and organization_id=target_provider_id returning id into rid;if rid is null then raise exception 'Calculator plugin not found' using errcode='40001';end if;end if;perform private.write_audit_event(auth.uid(),target_provider_id,case when target_id is null then 'calculator.plugin_created' else 'calculator.plugin_updated' end,'calculator_plugin',rid::text,jsonb_build_object('plugin_kind',target_plugin_kind));return rid;end $$;
grant execute on function public.admin_save_calculator_plugin(uuid,uuid,text,text,text,text,text) to authenticated;

create or replace function public.admin_save_calculator_version(target_id uuid,target_provider_id uuid,target_plugin_id uuid,target_version text,target_manifest jsonb,target_input_schema jsonb,target_output_schema jsonb,target_unit_schema jsonb,target_engine_reference text,target_dosing_mode text,target_checksum text) returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin if not private.has_permission(target_provider_id,'calculator.manage') then raise exception 'Calculator administration permission required' using errcode='42501';end if;if target_id is null then insert into public.calculator_plugin_versions(organization_id,plugin_id,version,manifest,input_schema,output_schema,unit_schema,engine_reference,dosing_mode,checksum,created_by_user_id) values(target_provider_id,target_plugin_id,target_version,coalesce(target_manifest,'{}'),coalesce(target_input_schema,'{}'),coalesce(target_output_schema,'{}'),coalesce(target_unit_schema,'{}'),coalesce(target_engine_reference,''),target_dosing_mode,coalesce(target_checksum,''),auth.uid()) returning id into rid;else update public.calculator_plugin_versions set manifest=coalesce(target_manifest,'{}'),input_schema=coalesce(target_input_schema,'{}'),output_schema=coalesce(target_output_schema,'{}'),unit_schema=coalesce(target_unit_schema,'{}'),engine_reference=coalesce(target_engine_reference,''),dosing_mode=target_dosing_mode,checksum=coalesce(target_checksum,''),updated_at=now() where id=target_id and organization_id=target_provider_id and status='draft' returning id into rid;if rid is null then raise exception 'Only draft calculator versions can be edited' using errcode='40001';end if;end if;perform private.write_audit_event(auth.uid(),target_provider_id,case when target_id is null then 'calculator.version_created' else 'calculator.version_updated' end,'calculator_plugin_version',rid::text,jsonb_build_object('plugin_id',target_plugin_id,'version',target_version,'dosing_mode',target_dosing_mode));return rid;end $$;
grant execute on function public.admin_save_calculator_version(uuid,uuid,uuid,text,jsonb,jsonb,jsonb,jsonb,text,text,text) to authenticated;

create or replace function public.transition_calculator_version(target_version_id uuid,target_status text) returns uuid language plpgsql security definer set search_path='' as $$declare v public.calculator_plugin_versions;ok boolean:=false;begin select * into v from public.calculator_plugin_versions where id=target_version_id for update;if v.id is null then raise exception 'Calculator version not found' using errcode='40001';end if;if target_status='review' and v.status='draft' and private.has_permission(v.organization_id,'calculator.manage') then ok=true;elsif target_status='approved' and v.status='review' and private.has_permission(v.organization_id,'calculator.manage') then ok=true;update public.calculator_plugin_versions set approved_by_user_id=auth.uid(),approved_at=now() where id=v.id;elsif target_status='published' and v.status='approved' and private.has_permission(v.organization_id,'calculator.manage') then ok=true;update public.calculator_plugin_versions set published_by_user_id=auth.uid(),published_at=now() where id=v.id;elsif target_status='archived' and v.status='published' and private.has_permission(v.organization_id,'calculator.manage') then ok=true;else raise exception 'Invalid calculator lifecycle transition' using errcode='42501';end if;update public.calculator_plugin_versions set status=target_status,updated_at=now() where id=v.id;perform private.write_audit_event(auth.uid(),v.organization_id,'calculator.version_'||target_status,'calculator_plugin_version',v.id::text,jsonb_build_object('old_status',v.status,'new_status',target_status,'dosing_mode',v.dosing_mode));return v.id;end $$;
grant execute on function public.transition_calculator_version(uuid,text) to authenticated;

create or replace function public.admin_link_calculator_source(target_provider_id uuid,target_plugin_version_id uuid,target_library_item_id uuid,target_library_version_id uuid,target_relationship_type text) returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin if not private.has_permission(target_provider_id,'calculator.manage') then raise exception 'Calculator administration permission required' using errcode='42501';end if;insert into public.calculator_plugin_source_links(organization_id,plugin_version_id,library_item_id,library_version_id,relationship_type,created_by_user_id) values(target_provider_id,target_plugin_version_id,target_library_item_id,target_library_version_id,target_relationship_type,auth.uid()) returning id into rid;perform private.write_audit_event(auth.uid(),target_provider_id,'calculator.source_linked','calculator_plugin_source_link',rid::text,jsonb_build_object('plugin_version_id',target_plugin_version_id,'library_version_id',target_library_version_id,'relationship_type',target_relationship_type));return rid;end $$;
grant execute on function public.admin_link_calculator_source(uuid,uuid,uuid,uuid,text) to authenticated;

create or replace function public.save_personal_calculator_configuration(target_id uuid,target_provider_id uuid,target_plugin_version_id uuid,target_name text,target_configuration jsonb,target_status text,target_expected_version integer default null) returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin if not private.has_permission(target_provider_id,'calculator.personal') or not exists(select 1 from public.organization_memberships where organization_id=target_provider_id and user_id=auth.uid() and status='active') then raise exception 'Personal calculator permission required' using errcode='42501';end if;if target_id is null then insert into public.calculator_personal_configurations(organization_id,owner_user_id,plugin_version_id,name,configuration,status) values(target_provider_id,auth.uid(),target_plugin_version_id,trim(target_name),coalesce(target_configuration,'{}'),target_status) returning id into rid;else update public.calculator_personal_configurations set name=trim(target_name),configuration=coalesce(target_configuration,'{}'),status=target_status,version=version+1,updated_at=now() where id=target_id and organization_id=target_provider_id and owner_user_id=auth.uid() and (target_expected_version is null or version=target_expected_version) returning id into rid;if rid is null then raise exception 'Personal configuration not found or stale' using errcode='40001';end if;end if;insert into public.calculator_configuration_events(organization_id,configuration_id,action,metadata,actor_user_id) values(target_provider_id,rid,case when target_id is null then 'calculator.personal_created' else 'calculator.personal_updated' end,jsonb_build_object('plugin_version_id',target_plugin_version_id),auth.uid());perform private.write_audit_event(auth.uid(),target_provider_id,case when target_id is null then 'calculator.personal_created' else 'calculator.personal_updated' end,'calculator_personal_configuration',rid::text,jsonb_build_object('plugin_version_id',target_plugin_version_id));return rid;end $$;
grant execute on function public.save_personal_calculator_configuration(uuid,uuid,uuid,text,jsonb,text,integer) to authenticated;

create or replace function public.get_personal_calculator_configurations(target_provider_id uuid) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'plugin_version_id',c.plugin_version_id,'name',c.name,'configuration',c.configuration,'status',c.status,'version',c.version) order by c.name),'[]') from public.calculator_personal_configurations c where c.organization_id=target_provider_id and c.owner_user_id=auth.uid() and private.has_permission(target_provider_id,'calculator.personal');$$;
grant execute on function public.get_personal_calculator_configurations(uuid) to authenticated;

commit;
